method derivative(xs: seq<int>) returns (result: seq<int>)
    requires |xs| > 0
    ensures |result| == |xs| - 1
    ensures forall i :: 0 <= i < |result| ==> result[i] == xs[i + 1] * (i + 1)
{
    var n := |xs|;
    var res := new int[n - 1];
    var i := 0;
    while i < n - 1
        invariant 0 <= i <= n - 1
        invariant |res| == n - 1
    {
        res[i] := xs[i + 1] * (i + 1);
        i := i + 1;
    }
    result := res;
}
```

